def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return [row[:] for row in grid]
    cr = sum(r for r, c in pts) / len(pts)
    cc = sum(c for r, c in pts) / len(pts)

    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, rc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= rc < w) or grid[rr][rc] != color:
                    continue
                key = tuple(sorted(((r, c), (rr, rc))))
                if key in seen:
                    continue
                seen.add(key)

                # Extend outward from the pair endpoint farther from the
                # overall colored motif.
                d1 = (r - cr) ** 2 + (c - cc) ** 2
                d2 = (rr - cr) ** 2 + (rc - cc) ** 2
                if d1 > d2:
                    sr, sc, step_r, step_c = r, c, -dr, -dc
                else:
                    sr, sc, step_r, step_c = rr, rc, dr, dc

                nr, nc = sr + step_r, sc + step_c
                while 0 <= nr < h and 0 <= nc < w and out[nr][nc] == bg:
                    out[nr][nc] = color
                    nr += step_r
                    nc += step_c
    return out
